        visited = [False] * n
        returnable = [False] * n

        def dfs(room, direction):
            if visited[room]:
                return True
            visited[room] = True
            next_room = (room + 1) % n if direction == 1 else (room - 1) % n
            if s[next_room] == '-' or (s[next_room] == '>' and direction == 1) or (s[next_room] == '<' and direction == -1):
                return dfs(next_room, direction)
            return False

        for i in range(n):
            if not visited[i]:
                visited = [False] * n
                if dfs(i, 1) and dfs(i, -1):
                    returnable[i] = True

        results.append(sum(returnable))

    return results

