import sys

def count_returnable_rooms(t, test_cases):
    results = []
    for n, s in test_cases:
        # Initialize counters for each room
        forward = [0] * n
        backward = [0] * n

        # Calculate forward and backward reachability
        for i in range(n):
            if s[i] == '>':
                forward[(i + 1) % n] += 1
            elif s[i] == '<':
                backward[(i - 1) % n] += 1
            else:
                forward[(i + 1) % n] += 1
                backward[(i - 1) % n] += 1

        # Check if a room is returnable
        returnable_count = 0
        for i in range(n):
            if forward[i] > 0 and backward[i] > 0:
                returnable_count += 1

        results.append(returnable_count)

    return results

